1	package br.com.loja.checkout;
2	
3	import static br.com.loja.checkout.Dinheiro.centavos;
4	
5	import java.math.BigDecimal;
6	import java.util.List;
7	import java.util.Objects;
8	
9	import org.springframework.stereotype.Service;
10	
11	import br.com.loja.checkout.clube.NivelClube;
12	import br.com.loja.checkout.cupom.ContextoCupom;
13	import br.com.loja.checkout.cupom.Cupom;
14	import br.com.loja.checkout.entrega.ModalidadeEntrega;
15	import br.com.loja.checkout.pagamento.FormaPagamento;
16	import br.com.loja.checkout.pagamento.Pagamento;
17	
18	/** Parte comum a todos os pedidos: ordem do cálculo, das validações e arredondamento. */
19	@Service
20	public class CalculadoraResumo {
21	
22	    private final Catalogo<NivelClube> niveis;
23	    private final Catalogo<ModalidadeEntrega> modalidades;
24	    private final Catalogo<Cupom> cupons;
25	    private final Catalogo<FormaPagamento> formasPagamento;
26	
27	    public CalculadoraResumo(List<NivelClube> niveis, List<ModalidadeEntrega> modalidades,
28	            List<Cupom> cupons, List<FormaPagamento> formasPagamento) {
29	        this.niveis = new Catalogo<>(niveis);
30	        this.modalidades = new Catalogo<>(modalidades);
31	        this.cupons = new Catalogo<>(cupons);
32	        this.formasPagamento = new Catalogo<>(formasPagamento);
33	    }
34	
35	    public ResumoResponse calcular(PedidoRequest pedido) {
36	        List<ItemPedido> itens = validarItens(pedido.itens());
37	        NivelClube nivel = niveis.buscar(pedido.nivelClube())
38	                .orElseThrow(() -> new CheckoutException(CodigoErro.NIVEL_CLUBE_INVALIDO));
39	        Regiao regiao = Regiao.buscar(pedido.regiao())
40	                .orElseThrow(() -> new CheckoutException(CodigoErro.REGIAO_INVALIDA));
41	        ModalidadeEntrega modalidade = modalidades.buscar(pedido.modalidadeEntrega())
42	                .orElseThrow(() -> new CheckoutException(CodigoErro.MODALIDADE_INVALIDA));
43	
44	        BigDecimal peso = somar(itens.stream().map(ItemPedido::pesoTotal).toList());
45	        if (!modalidade.atende(peso)) {
46	            throw new CheckoutException(CodigoErro.MODALIDADE_INDISPONIVEL);
47	        }
48	
49	        BigDecimal subtotal = centavos(somar(itens.stream().map(ItemPedido::valorTotal).toList()));
50	        BigDecimal frete = centavos(nivel.freteCobrado(centavos(modalidade.frete(peso))));
51	        BigDecimal desconto = descontoCupom(pedido.cupom(), new ContextoCupom(itens, subtotal, frete));
52	        BigDecimal seguro = regiao.seguro(subtotal);
53	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
54	
55	        FormaPagamento forma = formasPagamento.buscar(pedido.formaPagamento())
56	                .orElseThrow(() -> new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INVALIDA));
57	        int parcelas = Objects.requireNonNullElse(pedido.parcelas(), 1);
58	        if (!forma.aceitaParcelas(parcelas)) {
59	            throw new CheckoutException(CodigoErro.PARCELAMENTO_INVALIDO);
60	        }
61	        if (!forma.disponivel(totalPedido)) {
62	            throw new CheckoutException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
63	        }
64	        Pagamento pagamento = forma.pagar(totalPedido, parcelas);
65	        BigDecimal totalFinal = centavos(pagamento.totalFinal());
66	
67	        return new ResumoResponse(
68	                subtotal,
69	                desconto,
70	                frete,
71	                modalidade.prazoDias(),
72	                seguro,
73	                totalFinal.subtract(totalPedido),
74	                totalFinal,
75	                parcelas,
76	                centavos(pagamento.valorParcela()),
77	                centavos(nivel.credito(subtotal)),
78	                nivel.brinde(subtotal));
79	    }
80	
81	    private static List<ItemPedido> validarItens(List<ItemPedido> itens) {
82	        if (itens == null || itens.isEmpty() || !itens.stream().allMatch(i -> i != null && i.valido())) {
83	            throw new CheckoutException(CodigoErro.PEDIDO_INVALIDO);
84	        }
85	        return itens;
86	    }
87	
88	    private BigDecimal descontoCupom(String codigo, ContextoCupom contexto) {
89	        if (codigo == null) {
90	            return centavos(BigDecimal.ZERO);
91	        }
92	        Cupom cupom = cupons.buscar(codigo).orElseThrow(() -> new CheckoutException(CodigoErro.CUPOM_INVALIDO));
93	        if (!cupom.aplicavel(contexto)) {
94	            throw new CheckoutException(CodigoErro.CUPOM_NAO_APLICAVEL);
95	        }
96	        return centavos(cupom.desconto(contexto));
97	    }
98	
99	    private static BigDecimal somar(List<BigDecimal> valores) {
100	        return valores.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
101	    }
102	}
