2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	import org.springframework.stereotype.Component;
8	
9	import br.com.loja.checkout.Dinheiro;
10	
11	@Component
12	public class Cartao implements FormaPagamento {
13	
14	    private static final int MAXIMO_PARCELAS = 12;
15	    private static final int MAXIMO_SEM_JUROS = 3;
16	    private static final BigDecimal JUROS_MENSAL = new BigDecimal("0.0199");
17	
18	    @Override
19	    public String codigo() {
20	        return "CARTAO";
21	    }
22	
23	    @Override
24	    public boolean aceitaParcelas(int parcelas) {
25	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
26	    }
27	
28	    @Override
29	    public boolean disponivel(BigDecimal totalPedido) {
30	        return true;
31	    }
32	
33	    @Override
34	    public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
35	        if (parcelas <= MAXIMO_SEM_JUROS) {
36	            BigDecimal parcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
37	            return new Pagamento(totalPedido, parcela);
38	        }
39	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
40	        return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
41	    }
42	
43	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
44	    private static BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
45	        MathContext mc = MathContext.DECIMAL128;
46	        BigDecimal fator = BigDecimal.ONE.add(JUROS_MENSAL).pow(-parcelas, mc);
47	        return total.multiply(JUROS_MENSAL).divide(BigDecimal.ONE.subtract(fator), mc);
48	    }
49	}
